        {"a": "\ud83c\udfb5\ud83c\udfb5\u0301\ud800\udf48a\u0301 \u3000\u591a\u0301za \u0301\u0301\u00e9\ud83d\udd25a\u3000\u5b87\u591a\ud83c\udfb5a\u591a\ud800\udf48 \ud83c\udfb5\u00e9 z\u3000\ud83c\udfb5\ud800\udf48e\u0301bze\u0301b\u0301\u3000\ud83d\udd25\ud83c\udfb5z\ud83d\udd25\ud800\udf48z\u0301\ud83c\udfb5\u0301\u5b87\ud800\udf48zb\ud83c\udfb5e\u0301\u5b87\u0301a\ud83c\udfb5abzz\u3000\u00e9\u3000\ud83d\udd25\u3000\ud83d\udd25\u5b87\u5b87 z\ud83c\udfb5\u00e9\u5b87\u00e9\u00e9\ud800\udf48z\u0301b\u5b87\ud83d\udd25\ud800\udf48e\u0301\u5b87\u00e9\u3000a\u5b87\ud83c\udfb5\u00e9\u591ab \u3000 be\u0301\ud83c\udfb5e\u0301\u591a\u5b87\u00e9b\u591ab \u0301\u3000e\u0301\u00e9\u591aa\ud83c\udfb5\u591a\u00e9\u591az\u00e9\ud83c\udfb5\u591a\u00e9\ud800\udf48\ud83c\udfb5a\ud83d\udd25e\u0301\u3000\u591a \ud800\udf48\u3000e\u0301\u00e9a\u3000 \u3000a\ud800\udf48\u591a\ud83c\udfb5\u5b87be\u0301\u0301\u591a\u591a\ud800\udf48zbz\u5b87e\u0301az\u5b87\ud800\udf48\u591aa\u0301b \ud83d\udd25b\u00e9bz\u5b87 \u0301\ud83d\udd25z\u591a\ud800\udf48    \u0301\u591a\u00e9\u00e9a\ud83d\udd25z\u3000e\u0301  e\u0301\u3000z\u0301\u0301\ud83d\udd25e\u0301\ud800\udf48b\u5b87\ud83c\udfb5z\u0301be\u0301\ud800\udf48\ud800\udf48\ud83c\udfb5 \u3000e\u0301\u00e9\u5b87\u00e9z\u5b87\u3000\u0301\u00e9az\u0301\ud83d\udd25\ud83d\udd25z", "b": "\u0301\u5b87e\u0301\u0301\u3000\ud800\udf48 \ud83c\udfb5b\u0301e\u0301\ud800\udf48\ud83d\udd25\u591a\ud800\udf48\u5b87\u0301e\u0301\u00e9e\u0301\ud800\udf48 \ud800\udf48a\u3000a\u3000\u0301z\u00e9\u3000\ud83c\udfb5\u00e9z\u0301z\u591a \ud83d\udd25zb\u591ab\ud83d\udd25a \ud83d\udd25a\u00e9\u3000az\u591a\u3000\ud83d\udd25\ud800\udf48\u5b87a\u591a\u00e9\u5b87z\ud83d\udd25\ud83d\udd25a\ud800\udf48\ud800\udf48\u5b87b\u3000\u591a\u00e9b\ud800\udf48b\u00e9e\u0301\ud83c\udfb5a\u5b87z\u3000\u3000\u00e9\ud800\udf48e\u0301\ud83c\udfb5a\u3000b\u3000\ud83d\udd25\u5b87 \ud800\udf48\u591a\ud800\udf48 \u5b87\u3000\ud800\udf48\ud800\udf48 \u0301\u591ae\u0301\u00e9\u5b87\u5b87 be\u0301