        {"a": "\u3000e\u0301\u00e9\u591a azz\ud83c\udfb5\u00e9\u3000\u5b87\ud83c\udfb5\u591a\u0301\ud83c\udfb5\u591aa\u00e9\u3000e\u0301be\u0301\u591a\ud800\udf48\u00e9\ud83c\udfb5\ud800\udf48\u0301\u591abe\u0301\ud800\udf48\u0301\u0301z\u591a\u5b87a\ud83c\udfb5\u00e9\u5b87 \ud83d\udd25bb\u5b87\u3000\ud83c\udfb5\u3000\u00e9\ud800\udf48\u5b87\u00e9\u5b87\ud83c\udfb5aa\u3000\ud83d\udd25\u0301\u00e9 \ud800\udf48\u591azbz\ud83c\udfb5 ab\ud83c\udfb5az\u0301\u00e9 \u5b87\ud800\udf48b\u3000\u00e9\u3000e\u0301b ae\u0301\ud83c\udfb5a\u5b87\ud83c\udfb5zze\u0301e\u0301\ud83d\udd25\u00e9e\u0301zz\u00e9\u5b87\u3000 \ud83d\udd25e\u0301\ud83d\udd25\ud800\udf48\ud800\udf48\u3000z\ud83c\udfb5\ud83d\udd25\u591a\ud800\udf48aaa\ud83c\udfb5\u591azb\ud800\udf48\ud800\udf48 \u591aa\u3000b\ud83d\udd25b\u00e9\ud83d\udd25z\ud83d\udd25a\ud83c\udfb5b z\u0301\ud83d\udd25e\u0301a\ud83d\udd25\ud800\udf48\u5b87\ud83d\udd25a\u591aa\u5b87b\u0301\ud83c\udfb5\u591a\u3000 \ud83c\udfb5\u00e9\u591aa\u5b87 \u00e9\u3000\ud800\udf48 \u0301b\u591aa\u3000\ud83c\udfb5b ae\u0301b ze\u0301a\ud83c\udfb5\ud800\udf48e\u0301 zb\ud83d\udd25\u591a\u0301\u5b87\ud83d\udd25a\u00e9\ud83d\udd25\u591ab\u00e9", "b": "\ud83d\udd25z\u591a \ud83d\udd25\u3000b\u0301\ud800\udf48\u591az\u3000ze\u0301b\u0301\u3000\ud83d\udd25  \u0301 \u3000bba\u591a\u591a\u5b87\u5b87\u3000 aa\u591a \ud83d\udd25e\u0301\u0301\u3000\ud83d\udd25\ud83c\udfb5 \u591ab\u5b87\ud800\udf48ba\ud83d\udd25 \ud83d\udd25\ud83c\udfb5\ud800\udf48b\u3000\u3000 bb\u3000\u00e9 z\u5b87\u00e9\u5b87\ud800\udf48ze\u0301\u0301e\u0301a\u00e9b\u3000za\ud83d\udd25z\u00e9\ud83c\udfb5\ud800\udf48\u591a\u5b87\u00e9\ud83d\udd25\ud83c\udfb5 \ud83c\udfb5\ud83c\udfb5\u5b87\ud83c\udfb5 be\u0301\u5b87\u00e9\u5b87\u00e9 \u591a\u5b87z\u5b87b\ud83d\udd25\u591a ze\u0301\ud83c\udfb5\u591a \ud83c\udfb5\ud800\udf48\u00e9\u3000 \ud83d\udd25e\u0301\u591a\u591a\u0301a\u5b87\u3000\u00e9a\u0301\u5b87b\ud83c\udfb5  \u00e9e\u0301\u5b87e\u0301e\u0301\ud83d\udd25b\ud83c\udfb5\ud800\udf48\u5b87za\u591a