        {"a": "z\ud800\udf48\u00e9 e\u0301\ud800\udf48\u3000e\u0301be\u0301\u591a\u0301a \ud83c\udfb5\u3000\u00e9e\u0301\ud83c\udfb5\ud83c\udfb5e\u0301e\u0301\u3000b\u5b87\ud800\udf48\ud83d\udd25az\u0301\u3000b\u0301\u00e9\ud83c\udfb5\u00e9\ud800\udf48\u0301\u00e9baae\u0301\ud83c\udfb5\ud83c\udfb5\u00e9\ud83c\udfb5z\u5b87\u00e9\u00e9\u5b87z\ud800\udf48\u591a\ud83c\udfb5a\u591a b\u591ae\u0301\u00e9\ud800\udf48e\u0301a b\ud83d\udd25a\u00e9za\u3000\ud800\udf48\ud800\udf48\ud800\udf48\u00e9z\ud83c\udfb5\u00e9\ud800\udf48b\ud83d\udd25\u591a\u0301\u591ae\u0301e\u0301\u0301\u00e9\u591a\ud800\udf48\u00e9\ud83c\udfb5\ud83d\udd25e\u0301\ud83d\udd25\ud83d\udd25 \ud800\udf48\u00e9b\u591a\ud83d\udd25\ud83c\udfb5b\u00e9e\u0301\ud800\udf48\u3000e\u0301b\u0301\ud83d\udd25aaz\u591ab\ud83c\udfb5\u00e9\u00e9\u0301b\u0301a \u00e9ze\u0301\u0301 e\u0301b\u0301\u00e9bb\ud800\udf48\u00e9z\u0301  \u0301\u3000bz\u3000\u0301z\u00e9\u3000az\u5b87\u5b87\u00e9z\u00e9 \u0301zz\u3000\u5b87 \ud800\udf48\u0301\ud800\udf48e\u0301\ud83d\udd25\ud83c\udfb5\u00e9z\u0301e\u0301\ud83d\udd25b \ud83c\udfb5 \u5b87\u5b87\ud83d\udd25\ud83c\udfb5\u3000 \ud800\udf48 \u5b87\u591a\u591az\u00e9\u00e9\u5b87z\u00e9\ud83c\udfb5    a\u00e9\u3000\u0301\u0301\ud800\udf48\u591a\u00e9\ud800\udf48\ud83d\udd25b\ud83d\udd25bz\u5b87 aa\ud83d\udd25\ud800\udf48\u0301\u0301\u591a\u591a\u591azz\u3000\u3000\u00e9\ud800\udf48\ud83c\udfb5b\ud800\udf48\ud800\udf48\u3000\ud800\udf48\u0301\u5b87\u591a\u591a  \u3000a\ud83d\udd25\ud800\udf48\u0301\u0301\u3000\ud83c\udfb5", "b": "\u5b87\u3000b\ud83c\udfb5\u0301\u0301 \ud83d\udd25\u00e9a\u0301\u591az\ud83c\udfb5\u5b87b\u0301b\u0301a \u0301\u00e9\ud83d\udd25a\ud83c\udfb5\ud800\udf48\u591az\u0301\u0301a\u3000 b\u0301\ud83d\udd25\ud83c\udfb5\u00e9\u3000\u591a\u0301\ud83c\udfb5\u00e9\u00e9a\u5b87e\u0301e\u0301\ud800\udf48b\u00e9a\u3000\u5b87a\u3000\ud83d\udd25 e\u0301\u591ab\ud83c\udfb5\ud83d\udd25aaa\u3000ze\u0301a\u00e9b\u00e9\u591abe\u0301\u591a\ud83d\udd25a\ud83c\udfb5\u591a\ud83d\udd25\ud83